fn replace_with_colon(str1: &Vec<char>) -> Vec<char> {
    // Create a new vector with the same length as the input
    let mut result = Vec::with_capacity(str1.len());
    
    // Iterate through each character in the input vector
    for &c in str1.iter() {
        // Check if the character is a space, comma, or period
        if c == ' ' || c == ',' || c == '.' {
            result.push(':'); // Replace with colon
        } else {
            result.push(c); // Keep the original character
        }
    }
    
    result // Return the transformed vector
}